func:
// === Lecture brute des entités HA (climatisation / chauffage gratuits) ===
// Getters uniquement, pas de logique métier. Unités décrites par une liste
// ORDONNÉE (priorité décroissante) dans CLIM_UNITS, réordonnable depuis HA par
// le helper CLIM_PRIORITY_HELPER. Température de chaque pièce lue sur
// l'attribut `current_temperature` de l'unité, aucune sonde externe nécessaire.
// PREREQUIS : cocher "Enable global context store" sur le nœud serveur HA.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

let g;
try {
    g = global.get('homeassistant').homeAssistant.states;
    if (!g) throw new Error('states indisponibles');
} catch (e) {
    node.warn('HA indisponible, tick ignoré : ' + e.message);
    return null;
}

const eStr = (k, def) => {
    const v = env.get(k);
    return (v === undefined || v === null || v === '') ? def : String(v);
};
const eNum = (k, def) => {
    const v = parseFloat(env.get(k));
    return isNaN(v) ? def : v;
};
const numOrNull = (id) => {
    const raw = g[id]?.state;
    if (raw === undefined || raw === 'unavailable' || raw === 'unknown') return null;
    const v = parseFloat(raw);
    return isNaN(v) ? null : v;
};
const n = (id, def) => { const v = numOrNull(id); return v == null ? def : v; };
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const list = (s) => s.split(',').map(x => x.trim()).filter(x => x.length > 0);
const now = Date.now();
msg.now = now;

// --- Constantes du modèle ---
msg.minRunMs = clamp(eNum('CLIM_MIN_RUN_MIN', 20), 0, 240) * 60000;
msg.minOffMs = clamp(eNum('CLIM_MIN_OFF_MIN', 15), 0, 240) * 60000;
msg.confirmMs = clamp(eNum('CLIM_CONFIRM_MIN', 3), 1, 30) * 60000;
msg.storeBand = clamp(eNum('CLIM_STORE_BAND', 1.5), 0, 6);
msg.coolFloor = eNum('CLIM_COOL_FLOOR', 21);
msg.heatCeiling = eNum('CLIM_HEAT_CEILING', 23);
msg.outdoorCoolMin = eNum('CLIM_OUTDOOR_COOL_MIN', 24);
msg.outdoorHeatMax = eNum('CLIM_OUTDOOR_HEAT_MAX', 17);
msg.maxUnits = Math.round(clamp(eNum('CLIM_MAX_UNITS', 5), 1, 20));
msg.exportMargin = clamp(eNum('CLIM_EXPORT_MARGIN_W', 50), -500, 1000);
msg.defaultUnitW = clamp(eNum('CLIM_UNIT_W', 500), 100, 5000);
msg.groupStandbyW = clamp(eNum('CLIM_GROUP_STANDBY_W', 5), 0, 200);

// --- Entités ---
const outdoorId = eStr('CLIM_OUTDOOR_SENSOR', 'sensor.exterieur_temperature');
msg.weatherEntity = eStr('CLIM_WEATHER_ENTITY', 'weather.forecast_maison');
const solarId = eStr('SOLAR_SENSOR', 'sensor.pince_amperemetrique_power_a');
const gridId = eStr('GRID_SENSOR', 'sensor.pince_amperemetrique_power_b');
msg.cumulusSensor = eStr('CUMULUS_SENSOR', 'sensor.cumulus_automation');

// --- Réglages utilisateur (helpers HA) ---
msg.enabled = g['input_boolean.clim_automation_enabled']?.state === 'on';
msg.targetCool = clamp(n('input_number.clim_target_cool', 25), 16, 32);
msg.targetHeat = clamp(n('input_number.clim_target_heat', 20), 10, 28);
// Import réseau toléré pour un BESOIN de confort (pièce hors de sa cible).
// Le stockage au-delà de la cible reste au seul surplus. Absent : 0 W.
msg.importAllowance = clamp(n('input_number.clim_import_allowance', 0), 0, 5000);

const SEASON_MAP = {
    auto: 'auto', froid: 'froid', chaud: 'chaud', 'arrêt': 'arret', arret: 'arret',
    cool: 'froid', heat: 'chaud', off: 'arret'
};
const seasonRaw = String(g['input_select.clim_season_mode']?.state || 'auto').toLowerCase();
msg.seasonMode = SEASON_MAP[seasonRaw] || 'auto';

// --- Température extérieure : sonde, sinon entité météo ---
msg.outdoorTemp = outdoorId ? numOrNull(outdoorId) : null;
msg.outdoorSource = msg.outdoorTemp != null ? 'sonde' : null;
if (msg.outdoorTemp == null) {
    const wt = parseFloat(g[msg.weatherEntity]?.attributes?.temperature);
    if (!isNaN(wt)) { msg.outdoorTemp = wt; msg.outdoorSource = 'météo'; }
}
msg.outdoorAvailable = msg.outdoorTemp != null;

// Prévision du jour et de demain, mémorisée par le nœud « Mémoriser prévision »
// (weather.get_forecasts, toutes les heures). Périmée après 6 h.
const fc = getF('forecast');
msg.forecast = (fc && now - fc.at < 6 * 3600 * 1000) ? fc : null;

// --- Mesures électriques ---
msg.solar = n(solarId, 0);
msg.gridPower = n(gridId, 0);   // > 0 import réseau, < 0 injection
msg.export = -msg.gridPower;

// --- Groupes de disjoncteurs intelligents (JSON) ---
let groupsRaw = env.get('CLIM_GROUPS');
let groupDefs = [];
try {
    if (Array.isArray(groupsRaw)) groupDefs = groupsRaw;
    else if (typeof groupsRaw === 'string' && groupsRaw.trim()) groupDefs = JSON.parse(groupsRaw);
} catch (e) {
    node.warn('CLIM_GROUPS illisible (JSON invalide), mesure par groupe désactivée : ' + e.message);
    groupDefs = [];
}
msg.groups = groupDefs.map(gr => {
    const swState = gr.switch ? g[gr.switch]?.state : undefined;
    return {
        name: gr.name || gr.switch || '?',
        switchId: gr.switch || null,
        // État inconnu : supposé alimenté, sinon une lecture manquante gèlerait le groupe
        breakerOn: (swState === 'on' || swState === 'off') ? swState === 'on' : true,
        breakerKnown: swState === 'on' || swState === 'off',
        powerSensor: gr.power || null,
        power: gr.power ? numOrNull(gr.power) : null,
        units: Array.isArray(gr.units) ? gr.units : []
    };
});
const groupOf = {};
for (const gr of msg.groups) for (const uid of gr.units) groupOf[uid] = gr;

// --- Unités, par ordre de priorité ---
const ids = list(eStr('CLIM_UNITS',
    'climate.salon_room_temperature,climate.daikinap21104_room_temperature,'
    + 'climate.chambre_tom_room_temperature,climate.chambre_didier_room_temperature,'
    + 'climate.chambre_marie_room_temperature'));
const labels = list(eStr('CLIM_UNIT_LABELS',
    'Salon,Cuisine,Chambre Tom,Chambre Didier,Chambre Marie'));

msg.units = ids.map((id, i) => {
    const st = g[id];
    const raw = st?.state;
    const available = raw !== undefined && raw !== 'unavailable' && raw !== 'unknown';
    // Repli sur le dernier état connu : un reboot HA ne vaut pas intervention manuelle
    const hvacMode = available ? raw : (getF('lastKnownHvac:' + id) || 'off');
    if (available) setF('lastKnownHvac:' + id, raw);
    const a = st?.attributes || {};
    const cur = parseFloat(a.current_temperature);
    const sp = parseFloat(a.temperature);
    const gr = groupOf[id] || null;
    return {
        id: id,
        label: labels[i] || id,
        priority: i + 1,
        group: gr ? gr.name : null,
        breakerOn: gr ? gr.breakerOn : true,
        available: available,
        hvacMode: hvacMode,
        on: hvacMode !== 'off',
        hvacAction: a.hvac_action || null,
        current: isNaN(cur) ? null : cur,
        tempAvailable: !isNaN(cur),
        setpoint: isNaN(sp) ? null : sp,
        spMin: isNaN(parseFloat(a.min_temp)) ? 16 : parseFloat(a.min_temp),
        spMax: isNaN(parseFloat(a.max_temp)) ? 30 : parseFloat(a.max_temp),
        spStep: parseFloat(a.target_temp_step) > 0 ? parseFloat(a.target_temp_step) : 0.5,
        modes: Array.isArray(a.hvac_modes) ? a.hvac_modes : []
    };
});

// --- Ordre de priorité pilotable depuis Home Assistant ---
// Jetons : entity_id, sa partie après « climate. », ou le libellé. Unité absente
// du helper : à la suite, dans l'ordre de CLIM_UNITS. Jeton inconnu : ignoré.
msg.priorityHelper = eStr('CLIM_PRIORITY_HELPER', 'input_text.clim_priority_order');
const rawOrder = g[msg.priorityHelper]?.state;
const orderUsable = rawOrder !== undefined && rawOrder !== 'unavailable'
    && rawOrder !== 'unknown' && String(rawOrder).trim() !== '';
msg.priorityOrderSource = 'env';
if (orderUsable) {
    const norm = (v) => String(v).trim().toLowerCase().replace(/^climate\./, '');
    const wanted = list(String(rawOrder)).map(norm);
    const taken = {};
    const ordered = [];
    for (const token of wanted) {
        const hit = msg.units.find(u => !taken[u.id]
            && (norm(u.id) === token || norm(u.label) === token));
        if (hit) { taken[hit.id] = true; ordered.push(hit); }
    }
    for (const u of msg.units) if (!taken[u.id]) ordered.push(u);
    if (ordered.length === msg.units.length) {
        msg.units = ordered;
        msg.units.forEach((u, i) => { u.priority = i + 1; });
        msg.priorityOrderSource = ordered.some((u, i) => u.id !== ids[i]) ? 'helper' : 'helper (identique)';
    }
}
msg.unitCount = msg.units.length;
msg.anyTempAvailable = msg.units.some(u => u.tempAvailable);

if (msg.anyTempAvailable) {
    setF('noTempSince', null);
    msg.noTempHours = 0;
} else {
    let ds = getF('noTempSince');
    if (!ds) { ds = now; setF('noTempSince', ds); }
    msg.noTempHours = Math.round((now - ds) / 360000) / 10;
}

// --- Cumulus ---
// La priorité de l'eau chaude est assurée côté cumulus : il compte la
// consommation que la clim rendrait (recoverable_w) dans son propre surplus et
// démarre sans attendre ; la clim n'a qu'à suivre le compteur.
// Exception symétrique : un cumulus qui chauffe pour le seul STOCKAGE (eau déjà
// à sa cible, règle plan_storage) passe après le confort. Sa consommation est
// alors comptée comme disponible pour la clim, qui la lui reprend ; il s'arrête
// de lui-même quand son surplus retombe sous son seuil.
const cu = g[msg.cumulusSensor];
msg.cumulusFound = !!cu;
const ca = (cu && cu.attributes) || {};
msg.cumulus = {
    enabled: ca.enabled === true,
    desired: ca.desired || null,
    draw: parseFloat(ca.cumulus_draw) || 0,
    rule: ca.rule || null,
    storageOnly: ca.rule === 'plan_storage',
    waterTemp: parseFloat(ca.water_temp),
    target: parseFloat(ca.target_temp),
    leadThreshold: parseFloat(ca.lead_threshold_w)
};

return msg;

// === Détection du pilotage manuel, unité par unité ===
//  - PROPRIÉTÉ : une unité allumée hors du flow n'est jamais touchée par lui
//    (owned = false). Le confort demandé explicitement passe avant l'économie.
//  - REPRISE EN MAIN : mode OU consigne changés hors du flow sur une unité
//    qu'il pilote → elle lui est retirée, pause de 45 min sur CETTE unité.
//    Le flow modulant lui-même la consigne, il mémorise celle qu'il a envoyée
//    pour ne pas prendre ses propres réglages pour ceux de l'utilisateur.
// États illisibles (reboot HA) ignorés.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const MANUAL_HOLD_MS = 45 * 60 * 1000;
const HA_LAG_GRACE_MS = 90 * 1000;
const SP_TOL = 0.3;
const now = msg.now;

for (const u of msg.units) {
    const K = ':' + u.id;
    let expected = getF('expectedHvac' + K);
    if (expected == null && u.available) {
        expected = u.hvacMode;
        setF('expectedHvac' + K, expected);
    }
    const prevActionAt = getF('lastActionAt' + K) || 0;
    let holdUntil = getF('holdUntil' + K) || 0;
    let owned = getF('owned' + K) === true;
    const expSp = getF('expectedSp' + K);
    const settled = now - prevActionAt > HA_LAG_GRACE_MS;

    const modeChanged = u.available && expected != null && u.hvacMode !== expected;
    const spChanged = u.available && owned && u.on && expSp != null && u.setpoint != null
        && Math.abs(u.setpoint - expSp) > SP_TOL;
    if (settled && (modeChanged || spChanged)) {
        holdUntil = now + MANUAL_HOLD_MS;
        setF('holdUntil' + K, holdUntil);
        setF('expectedHvac' + K, u.hvacMode);
        setF('expectedSp' + K, null);
        owned = false;
        setF('owned' + K, false);
        node.warn('Pilotage manuel détecté sur ' + u.label
            + (spChanged && !modeChanged ? ' (consigne ' + u.setpoint + ' °C)' : '') + ' → pause 45 min');
    }

    if (!u.on && owned) {
        owned = false;
        setF('owned' + K, false);
    }

    u.owned = owned;
    u.holdActive = now < holdUntil;
    u.holdUntil = holdUntil > now ? holdUntil : null;
    u.manualControl = u.on && !owned;
    u.commandedSp = owned ? expSp : null;
    const lastOnAt = getF('lastOnAt' + K) || 0;
    const lastOffAt = getF('lastOffAt' + K) || 0;
    u.minRunOk = now - lastOnAt >= msg.minRunMs;
    u.minOffOk = now - lastOffAt >= msg.minOffMs;
    u.minRunLeftMin = u.on ? Math.max(0, Math.ceil((msg.minRunMs - (now - lastOnAt)) / 60000)) : 0;
    u.minOffLeftMin = !u.on ? Math.max(0, Math.ceil((msg.minOffMs - (now - lastOffAt)) / 60000)) : 0;
}

msg.manualCount = msg.units.filter(u => u.manualControl).length;
msg.holdCount = msg.units.filter(u => u.holdActive).length;
return msg;

// === Bilan électrique et apprentissage de la puissance des unités ===
// Unités inverter : la puissance varie de 150 à 1000 W selon l'écart à la
// consigne, aucune valeur fixe ne la décrit. Elle est donc APPRISE sur les
// compteurs des disjoncteurs : quand une unité tourne seule sur son groupe,
// la mesure du groupe est la sienne. Plusieurs unités sur un groupe : la mesure
// est partagée au prorata de leur puissance apprise.
//
// recoverable_w = ce que le flow rendrait en coupant ce qu'il a allumé. Publié
// pour le flow cumulus, qui l'ajoute à son surplus : l'eau chaude démarre sans
// attendre que la clim lui laisse la place, la clim suit ensuite le compteur.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const now = msg.now;
const lastRun = getF('bilanLastRun');
const dtMs = lastRun ? clamp(now - lastRun, 0, 10 * 60000) : 0;
setF('bilanLastRun', now);
const ema = (prev, sample, tauMs) => {
    if (prev == null || isNaN(prev)) return sample;
    return prev + (1 - Math.exp(-dtMs / tauMs)) * (sample - prev);
};

// --- Export disponible, lissé (60 s) : une bouilloire ne doit pas faire bouger
// les consignes. Un cumulus en simple stockage cède sa consommation au confort.
msg.cumulusYieldW = msg.cumulus.storageOnly ? Math.max(0, Math.round(msg.cumulus.draw)) : 0;
const exportAvg = ema(getF('exportAvg'), msg.export + msg.cumulusYieldW, 60 * 1000);
setF('exportAvg', exportAvg);
msg.exportAvg = Math.round(exportAvg);

// --- Puissance par unité ---
const learned = (u) => {
    const v = getF('unitW:' + u.id);
    return v == null ? msg.defaultUnitW : v;
};
const metered = msg.groups.filter(gr => gr.power != null);
let climTotal = 0;
const accounted = {};
for (const gr of msg.groups) {
    const inGroup = msg.units.filter(u => gr.units.indexOf(u.id) !== -1);
    for (const u of inGroup) accounted[u.id] = true;
    const running = inGroup.filter(u => u.on);
    if (gr.power == null) {
        for (const u of running) { u.powerW = learned(u); u.powerSource = 'estimation'; climTotal += u.powerW; }
        continue;
    }
    const net = Math.max(0, gr.power - msg.groupStandbyW);
    climTotal += net;
    if (running.length === 1) {
        const u = running[0];
        u.powerW = net;
        u.powerSource = 'mesure';
        // Apprentissage hors démarrage (pic d'inrush) et hors veille compresseur
        if (dtMs > 0 && net > 60) {
            setF('unitW:' + u.id, Math.round(clamp(ema(getF('unitW:' + u.id), net, 30 * 60000), 100, 3000)));
        }
    } else if (running.length > 1) {
        const sum = running.reduce((a, u) => a + learned(u), 0);
        for (const u of running) {
            u.powerW = Math.round(net * learned(u) / sum);
            u.powerSource = 'prorata';
        }
    }
}
for (const u of msg.units) {
    if (!accounted[u.id] && u.on) { u.powerW = learned(u); u.powerSource = 'estimation'; climTotal += u.powerW; }
    if (!u.on) { u.powerW = 0; u.powerSource = null; }
    u.learnedW = learned(u);
    u.powerW = Math.round(u.powerW || 0);
}
msg.climTotal = Math.round(climTotal);
msg.recoverable = msg.units.filter(u => u.owned && u.on).reduce((a, u) => a + u.powerW, 0);
msg.metered = metered.length > 0;

// --- Énergie du jour consommée par les unités pilotées, et sa part solaire ---
const dayKey = new Date(now).toDateString();
let day = getF('energyDay');
if (!day || day.key !== dayKey) day = { key: dayKey, kwh: 0, solarKwh: 0 };
if (msg.recoverable > 0 && dtMs > 0) {
    const kwh = msg.recoverable * dtMs / 3600000 / 1000;
    day.kwh += kwh;
    day.solarKwh += kwh * clamp((msg.export + msg.recoverable) / msg.recoverable, 0, 1);
}
setF('energyDay', day);
msg.climKwhToday = Math.round(day.kwh * 100) / 100;
msg.climSolarShareToday = day.kwh > 0.05 ? Math.round(day.solarKwh / day.kwh * 100) : null;

return msg;

// === Besoin de confort, sens et plage de consigne, pièce par pièce ===
// Pour chaque pièce : faut-il refroidir / chauffer, et entre quelles consignes
// le routeur peut moduler la puissance de l'unité.
//   deep  : consigne de stockage (cible ∓ CLIM_STORE_BAND, bornée par
//           CLIM_COOL_FLOOR / CLIM_HEAT_CEILING) → puissance maximale
//   idle  : consigne au-delà de la température de la pièce → compresseur
//           au ralenti, l'unité ne consomme presque plus
// Le routeur fait glisser la consigne entre les deux pour suivre le surplus,
// comme un routeur solaire module une résistance.
//
// Saison (mode auto) : prévision du jour si disponible (maxi ≥ seuil froid,
// mini ≤ seuil chaud), sinon température extérieure, sinon l'écart intérieur
// tranche seul. Sens latché par unité pendant un cycle.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const seasonOff = msg.seasonMode === 'arret';
const fc = msg.forecast;
const outdoor = msg.outdoorAvailable ? msg.outdoorTemp : null;

let hotDay, coldDay;
if (fc && fc.todayMax != null && fc.todayMin != null) {
    hotDay = fc.todayMax >= msg.outdoorCoolMin;
    coldDay = fc.todayMin <= msg.outdoorHeatMax;
    msg.seasonBasis = 'prévision ' + fc.todayMin + '–' + fc.todayMax + ' °C';
} else if (outdoor != null) {
    hotDay = outdoor >= msg.outdoorCoolMin;
    coldDay = outdoor <= msg.outdoorHeatMax;
    msg.seasonBasis = 'extérieur ' + outdoor + ' °C (' + msg.outdoorSource + ')';
} else {
    hotDay = coldDay = true;
    msg.seasonBasis = 'aucune donnée extérieure';
}
const canCool = !seasonOff && (msg.seasonMode === 'froid' || (msg.seasonMode === 'auto' && hotDay));
const canHeat = !seasonOff && (msg.seasonMode === 'chaud' || (msg.seasonMode === 'auto' && coldDay));
msg.canCool = canCool;
msg.canHeat = canHeat;

const coolStore = Math.max(msg.targetCool - msg.storeBand, msg.coolFloor);
const heatStore = Math.min(msg.targetHeat + msg.storeBand, msg.heatCeiling);
msg.coolStore = Math.round(coolStore * 10) / 10;
msg.heatStore = Math.round(heatStore * 10) / 10;

const snap = (v, u) => {
    const s = u.spStep || 0.5;
    return Math.max(u.spMin, Math.min(u.spMax, Math.round(v / s) * s));
};

for (const u of msg.units) {
    u.needMode = 'none';
    u.comfortNeed = false;
    u.needReason = null;
    u.deepSp = null;
    u.idleSp = null;

    if (!u.available) { u.needReason = 'Unité injoignable'; setF('modeLatch:' + u.id, null); continue; }
    if (!u.tempAvailable) { u.needReason = 'Température de la pièce illisible'; setF('modeLatch:' + u.id, null); continue; }
    if (seasonOff) { u.needReason = 'Mode saison sur arrêt'; setF('modeLatch:' + u.id, null); continue; }

    const t = u.current;
    const latch = getF('modeLatch:' + u.id);
    const running = u.on && u.owned;
    let mode = 'none';
    if (canCool && t > msg.targetCool) mode = 'cool';
    else if (canHeat && t < msg.targetHeat) mode = 'heat';
    else if (canCool && t > coolStore && (latch === 'cool' || !canHeat)) mode = 'cool';      // stockage de fraîcheur
    else if (canHeat && t < heatStore && (latch === 'heat' || !canCool)) mode = 'heat';      // stockage de chaleur
    // Un cycle en cours garde son sens jusqu'au bout du stockage
    if (running && latch && mode !== latch) {
        if (latch === 'cool' && canCool && t > coolStore) mode = 'cool';
        if (latch === 'heat' && canHeat && t < heatStore) mode = 'heat';
    }

    u.modeSupported = mode === 'none' || u.modes.length === 0 || u.modes.indexOf(mode) !== -1;
    if (mode !== 'none' && !u.modeSupported) {
        u.needReason = 'Mode ' + mode + ' non exposé par l\'unité (' + u.modes.join(', ') + ')';
        setF('modeLatch:' + u.id, null);
        continue;
    }

    if (mode === 'cool') {
        u.comfortNeed = t > msg.targetCool;
        u.deepSp = snap(coolStore, u);
        // Au-dessus de la pièce : le compresseur ralentit puis s'arrête
        u.idleSp = snap(Math.max(msg.targetCool, t + 1), u);
        u.needReason = u.comfortNeed
            ? t + ' °C, au-dessus de la cible froid ' + msg.targetCool + ' °C'
            : 'Stockage de fraîcheur jusqu\'à ' + msg.coolStore + ' °C';
    } else if (mode === 'heat') {
        u.comfortNeed = t < msg.targetHeat;
        u.deepSp = snap(heatStore, u);
        u.idleSp = snap(Math.min(msg.targetHeat, t - 1), u);
        u.needReason = u.comfortNeed
            ? t + ' °C, sous la cible chaud ' + msg.targetHeat + ' °C'
            : 'Stockage de chaleur jusqu\'à ' + msg.heatStore + ' °C';
    } else if (!canCool && !canHeat) {
        u.needReason = 'Saison neutre (' + msg.seasonBasis + ')';
    } else {
        u.needReason = 'Confort assuré (' + t + ' °C)';
    }
    u.needMode = mode;
    setF('modeLatch:' + u.id, mode === 'none' ? null : mode);
}

msg.needCount = msg.units.filter(u => u.needMode !== 'none').length;
return msg;

// === Routeur solaire : la consigne des unités suit le surplus ===
//
// Priorité de la décision, de haut en bas :
//   1. Automatisation désactivée          → aucune commande
//   2. Unité hors périmètre (allumée à la main, pause 45 min, disjoncteur
//      coupé, injoignable)               → jamais touchée
//   3. Besoin disparu                     → arrêt (après le min-run)
//   4. Boucle de puissance sur le compteur :
//        écart = export lissé − marge + tolérance d'import
//      > 0 : consigne plus profonde (+ de puissance) sur l'unité la plus
//            prioritaire, puis démarrage de la suivante
//      < 0 : consigne relâchée vers le ralenti sur les moins prioritaires,
//            puis arrêt de la moins prioritaire une fois toutes au ralenti
//   5. Anti court-cycle par unité         → min-run / min-off
//
// L'eau chaude passe avant : le flow cumulus compte recoverable_w dans son
// surplus et démarre quand il veut ; le compteur bascule en import, la boucle
// relâche les consignes dans la minute. Aucune réservation à deviner ici.
//
// Tolérance d'import (input_number.clim_import_allowance) : appliquée seulement
// si une pièce pilotée est HORS de sa cible de confort. Le stockage (pièce déjà
// dans sa cible, surplus mis en réserve dans les murs) reste au seul surplus.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = msg.now;
const DEAD_W = 100;               // zone morte autour de la cible d'export
const STEP_UP_MS = 3 * 60000;     // une consigne plus profonde toutes les 3 min par unité
const STEP_DOWN_MS = 2 * 60000;   // relâchement plus réactif (chaque minute importée se paie)
const SETTLE_MS = 90 * 1000;      // délai global après toute modification (réponse de l'inverter)
const W_PER_DEG = 250;            // ordre de grandeur : W rendus par °C de consigne relâché
const START_FRACTION = 0.6;       // part de la puissance apprise exigée pour démarrer
const SHED_MS = 5 * 60000;        // import persistant, toutes unités au ralenti → arrêt
const IDLE_STOP_MS = 15 * 60000;  // ralenti prolongé sans surplus → arrêt

const path = [];
const step = (id, label, status, detail) => path.push({ id, label, status, detail: detail || null });
const toward = (from, to, deg) => (to > from ? Math.min(to, from + deg) : Math.max(to, from - deg));
const snap = (v, u) => {
    const s = u.spStep || 0.5;
    return Math.max(u.spMin, Math.min(u.spMax, Math.round(v / s) * s));
};
const spAt = (u) => getF('spAt:' + u.id) || 0;

for (const u of msg.units) { u.desired = null; u.desiredReason = null; u.targetSp = null; }

// --- 1. Automatisation désactivée ---
if (!msg.enabled) {
    for (const u of msg.units) { u.desired = 'skip'; u.desiredReason = 'automatisation désactivée'; }
    step('enabled', 'Automatisation active', 'hit', 'désactivée');
    setF('pendingStart', null);
    setF('pendingShedSince', null);
    msg.state = 'Désactivé';
    msg.reason = 'Automatisation désactivée, aucune commande envoyée';
    msg.decisionPath = path;
    msg.routerAction = 'none';
    return msg;
}
step('enabled', 'Automatisation active', 'pass');

// --- 2. Hors périmètre ---
let outCount = 0;
for (const u of msg.units) {
    if (u.manualControl) { u.desired = 'skip'; u.desiredReason = 'pilotée à la main, non modifiée'; }
    else if (u.breakerOn === false) { u.desired = 'skip'; u.desiredReason = 'disjoncteur ' + (u.group || '?') + ' coupé'; }
    else if (!u.available) { u.desired = 'skip'; u.desiredReason = 'injoignable, aucune commande'; }
    else if (u.holdActive && !u.on) { u.desired = 'skip'; u.desiredReason = 'pause après intervention manuelle'; }
    if (u.desired === 'skip') outCount++;
}
step('scope', 'Unités dans le périmètre', 'pass',
    outCount ? outCount + ' hors périmètre' : null);

// --- 3. Besoin disparu ---
const running = [];
let released = 0;
for (const u of msg.units) {
    if (u.desired || !u.owned || !u.on) continue;
    if (u.needMode === 'none') {
        if (u.minRunOk) {
            u.desired = 'off';
            u.desiredReason = u.needReason || 'plus de besoin';
            released++;
        } else {
            // Min-run : l'unité reste allumée, consigne au ralenti
            u.desired = 'on';
            u.targetSp = u.commandedSp != null ? u.commandedSp : u.setpoint;
            u.desiredReason = (u.needReason || 'plus de besoin') + ', arrêt dans ' + u.minRunLeftMin + ' min';
        }
    } else {
        running.push(u);
    }
}
step('release', 'Besoin toujours présent', 'pass', released ? released + ' unité(s) libérée(s)' : null);

// Consigne courante de chaque unité pilotée
for (const u of running) {
    let sp = u.commandedSp != null ? u.commandedSp : (u.setpoint != null ? u.setpoint : u.deepSp);
    // Bornes recalculées à chaque tick (cible changée, pièce qui évolue)
    const lo = Math.min(u.deepSp, u.idleSp), hi = Math.max(u.deepSp, u.idleSp);
    u.targetSp = snap(Math.max(lo, Math.min(hi, sp)), u);
    u.atDeep = u.targetSp === u.deepSp;
    u.atIdle = u.targetSp === u.idleSp;
}

// --- 4. Boucle de puissance ---
const anyComfortRunning = running.some(u => u.comfortNeed);
const eligible = msg.units.filter(u => !u.desired && !u.on && u.needMode !== 'none'
    && u.available && u.modeSupported && !u.holdActive)
    .sort((a, b) => a.priority - b.priority);
const nextUnit = eligible.find(u => u.minOffOk) || null;
const allowanceFor = (comfort) => (comfort ? msg.importAllowance : 0);
// Tolérance active si une pièce pilotée est hors de sa cible, ou pour démarrer
// la prochaine pièce hors de sa cible une fois les autres à pleine puissance.
const allowComfort = anyComfortRunning
    || (!!nextUnit && nextUnit.comfortNeed && running.every(u => u.atDeep));
msg.allowanceActive = allowComfort && msg.importAllowance > 0;
msg.errorW = Math.round(msg.exportAvg - msg.exportMargin + allowanceFor(allowComfort));
const lastChange = getF('lastChangeAt') || 0;
const settled = now - lastChange >= SETTLE_MS;
let action = 'hold';
let actionDetail = null;

if (msg.errorW > DEAD_W) {
    setF('pendingShedSince', null);
    // a) Puissance supplémentaire sur une unité déjà en marche, la plus prioritaire d'abord
    const deepen = running.slice().sort((a, b) => a.priority - b.priority)
        .find(u => !u.atDeep && now - spAt(u) >= STEP_UP_MS);
    const saturated = running.every(u => u.atDeep);
    if (deepen && settled) {
        deepen.targetSp = snap(toward(deepen.targetSp, deepen.deepSp, 0.5), deepen);
        deepen.spChanged = true;
        action = 'deepen';
        actionDetail = deepen.label + ' → ' + deepen.targetSp + ' °C';
        setF('pendingStart', null);
    } else if (saturated && nextUnit && running.length < msg.maxUnits) {
        // b) Démarrage de la suivante, si l'écart couvre sa puissance de démarrage
        const err = msg.errorW;
        const needW = Math.round(START_FRACTION * nextUnit.learnedW);
        nextUnit.startNeedW = needW;
        if (err >= needW) {
            const p = getF('pendingStart');
            if (p && p.id === nextUnit.id) {
                if (now - p.since >= msg.confirmMs && settled) {
                    nextUnit.desired = 'on';
                    nextUnit.startNow = true;
                    nextUnit.desiredReason = 'surplus ' + msg.exportAvg + ' W ≥ ' + needW + ' W de démarrage';
                    // Consigne de départ : cible de confort si besoin, sinon stockage doux
                    const start = nextUnit.comfortNeed
                        ? (nextUnit.needMode === 'cool' ? msg.targetCool : msg.targetHeat)
                        : (nextUnit.needMode === 'cool' ? nextUnit.current - 1 : nextUnit.current + 1);
                    const lo = Math.min(nextUnit.deepSp, nextUnit.idleSp), hi = Math.max(nextUnit.deepSp, nextUnit.idleSp);
                    nextUnit.targetSp = snap(Math.max(lo, Math.min(hi, start)), nextUnit);
                    action = 'start';
                    actionDetail = nextUnit.label;
                    setF('pendingStart', null);
                } else {
                    action = 'start_pending';
                    actionDetail = nextUnit.label + ' dans '
                        + Math.max(1, Math.ceil((msg.confirmMs - (now - p.since)) / 60000)) + ' min';
                }
            } else {
                setF('pendingStart', { id: nextUnit.id, since: now });
                action = 'start_pending';
                actionDetail = nextUnit.label + ' dans ' + Math.ceil(msg.confirmMs / 60000) + ' min';
            }
        } else {
            setF('pendingStart', null);
            action = 'hold';
            actionDetail = 'écart ' + err + ' W < ' + needW + ' W pour démarrer ' + nextUnit.label;
        }
    } else {
        if (!deepen) setF('pendingStart', null);
        actionDetail = saturated ? (nextUnit ? 'plafond d\'unités' : 'aucune autre pièce en demande')
            : 'stabilisation';
    }
} else if (msg.errorW < -DEAD_W) {
    setF('pendingStart', null);
    // a) Relâchement des consignes, moins prioritaires d'abord, proportionnel à l'écart
    let remaining = -msg.errorW;
    const relaxed = [];
    for (const u of running.slice().sort((a, b) => b.priority - a.priority)) {
        if (remaining <= 0) break;
        if (u.atIdle || now - spAt(u) < STEP_DOWN_MS) continue;
        const deg = Math.min(2, Math.max(0.5, Math.ceil(remaining / W_PER_DEG) * 0.5));
        const before = u.targetSp;
        u.targetSp = snap(toward(u.targetSp, u.idleSp, deg), u);
        if (u.targetSp !== before) {
            u.spChanged = true;
            remaining -= Math.abs(u.targetSp - before) * W_PER_DEG;
            relaxed.push(u.label + ' → ' + u.targetSp + ' °C');
        }
    }
    if (relaxed.length) {
        action = 'relax';
        actionDetail = relaxed.join(', ');
        setF('pendingShedSince', null);
    } else if (running.length && running.every(u => u.atIdle)) {
        // b) Toutes au ralenti et l'import persiste : arrêt de la moins prioritaire
        let since = getF('pendingShedSince');
        if (!since) { since = now; setF('pendingShedSince', now); }
        const victim = running.slice().sort((a, b) => b.priority - a.priority)[0];
        if (now - since >= SHED_MS) {
            if (victim.minRunOk) {
                victim.desired = 'off';
                victim.desiredReason = 'import persistant, consigne déjà au ralenti';
                action = 'stop';
                actionDetail = victim.label;
                setF('pendingShedSince', null);
            } else {
                action = 'stop_pending';
                actionDetail = victim.label + ', anti court-cycle ' + victim.minRunLeftMin + ' min';
            }
        } else {
            action = 'stop_pending';
            actionDetail = victim.label + ' dans ' + Math.ceil((SHED_MS - (now - since)) / 60000) + ' min';
        }
    } else {
        actionDetail = 'consignes en cours de relâchement';
    }
} else {
    setF('pendingStart', null);
    setF('pendingShedSince', null);
    actionDetail = 'surplus équilibré';
}

// Unité au ralenti depuis IDLE_STOP_MS sans que le surplus la relance : elle ne
// sert plus à rien, arrêt de la moins prioritaire (une par tick, après min-run).
for (const u of running) {
    if (u.targetSp === u.idleSp) { if (!getF('idleSince:' + u.id)) setF('idleSince:' + u.id, now); }
    else setF('idleSince:' + u.id, null);
}
if (action === 'hold' || action === 'stop_pending') {
    const idleVictim = running.slice().sort((a, b) => b.priority - a.priority)
        .find(u => !u.desired && u.targetSp === u.idleSp && u.minRunOk
            && now - (getF('idleSince:' + u.id) || now) >= IDLE_STOP_MS);
    if (idleVictim) {
        idleVictim.desired = 'off';
        idleVictim.desiredReason = 'au ralenti depuis ' + Math.round(IDLE_STOP_MS / 60000)
            + ' min, surplus absent';
        setF('idleSince:' + idleVictim.id, null);
        action = 'stop';
        actionDetail = idleVictim.label + ' (ralenti prolongé)';
    }
}
msg.routerAction = action;
msg.routerDetail = actionDetail;
step('router', 'Boucle de puissance', action === 'hold' ? 'pass' : 'hit',
    'écart ' + msg.errorW + ' W · ' + (actionDetail || action));

// Unités conservées, unités restantes
for (const u of running) {
    if (!u.desired) { u.desired = 'on'; u.desiredReason = u.needReason; }
}
for (const u of msg.units) {
    if (!u.desired) {
        u.desired = 'off';
        if (!u.desiredReason) {
            u.desiredReason = u.needMode === 'none' ? u.needReason
                : (u.on ? 'en attente' : (u.minOffOk ? 'en attente de surplus'
                    : 'anti court-cycle, ' + u.minOffLeftMin + ' min'));
        }
    }
}
const anyChange = msg.units.some(u => u.spChanged || u.startNow
    || (u.desired === 'off' && u.on && u.owned));
if (anyChange) setF('lastChangeAt', now);

// --- Synthèse ---
const onUnits = msg.units.filter(u => u.desired === 'on');
msg.activeLabels = onUnits.map(u => u.label);
msg.activeCount = onUnits.length;
const modes = onUnits.map(u => u.needMode);
const cumulusHeating = (msg.cumulus.draw > 0 || msg.cumulus.desired === 'on') && !msg.cumulus.storageOnly;
msg.cumulusHeating = cumulusHeating;

if (msg.activeCount > 0) {
    const cooling = modes.indexOf('cool') !== -1, heating = modes.indexOf('heat') !== -1;
    msg.state = (cooling && heating) ? 'Confort gratuit' : cooling ? 'Rafraîchissement gratuit' : 'Chauffage gratuit';
    const throttled = action === 'relax' || action === 'stop_pending'
        || (running.length > 0 && running.every(u => u.targetSp === u.idleSp));
    if (throttled) msg.state = cumulusHeating ? 'Ralenti (eau chaude prioritaire)' : 'Ralenti (surplus en baisse)';
    msg.reason = msg.activeLabels.join(', ') + ' · ' + (msg.recoverable || 0) + ' W · écart '
        + msg.errorW + ' W' + (actionDetail ? ' · ' + actionDetail : '')
        + (cumulusHeating ? ' · cumulus en chauffe, prioritaire' : '');
} else if (msg.manualCount > 0 && msg.needCount === 0) {
    msg.state = 'Pilotage manuel';
    msg.reason = msg.units.filter(u => u.manualControl).map(u => u.label).join(', ')
        + ' pilotée(s) à la main, non modifiée(s)';
} else if (msg.needCount === 0) {
    msg.state = msg.seasonMode === 'arret' ? 'Mode saison arrêté'
        : (!msg.canCool && !msg.canHeat) ? 'Hors saison' : 'Confort atteint';
    msg.reason = 'Aucune pièce en demande (' + msg.seasonBasis + ')';
} else if (action === 'start_pending') {
    msg.state = 'Démarrage différé';
    msg.reason = 'Surplus en cours de confirmation : ' + actionDetail;
} else if (cumulusHeating) {
    msg.state = 'Veille (eau chaude prioritaire)';
    msg.reason = 'Le cumulus chauffe sur le surplus, ' + msg.needCount + ' pièce(s) en attente';
} else {
    msg.state = 'Veille (surplus insuffisant)';
    msg.reason = 'Export ' + msg.exportAvg + ' W'
        + (nextUnit ? ', ' + Math.round(START_FRACTION * nextUnit.learnedW) + ' W pour démarrer ' + nextUnit.label : '');
}

msg.decisionPath = path;
return msg;

// === Émission des commandes, une par unité à changer ===
// Sortie 1 : un message par unité, cible portée par payload.target.entity_id
// (aucune entité en dur dans les nœuds de service).
//   service = 'start'    → set_hvac_mode puis set_temperature (chaînés)
//   service = 'setpoint' → set_temperature seul (modulation du routeur)
//   service = 'stop'     → turn_off
// Sortie 2 : le message de synthèse, vers le sensor et les alertes.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const SP_TOL = 0.2;
const now = msg.now;
const cmds = [];

for (const u of msg.units) {
    u.action = 'none';
    const K = ':' + u.id;
    if (u.desired === 'skip') continue;

    if (u.desired === 'on' && !u.on) {
        u.action = 'start';
        setF('lastOnAt' + K, now);
        setF('owned' + K, true);
        u.owned = true;
    } else if (u.desired === 'off' && u.on) {
        if (!u.owned) continue;              // le flow n'éteint que ce qu'il a allumé
        u.action = 'stop';
        setF('lastOffAt' + K, now);
        setF('owned' + K, false);
        setF('expectedSp' + K, null);
        u.owned = false;
    } else if (u.desired === 'on' && u.on && u.owned) {
        if (u.needMode !== 'none' && u.hvacMode !== u.needMode) {
            u.action = 'start';              // bascule de sens : mode + consigne
            u.desiredReason = (u.desiredReason || '') + ' · réalignement mode ' + u.needMode;
        } else if (u.targetSp != null
            && (u.spChanged || u.setpoint == null || Math.abs(u.setpoint - u.targetSp) > SP_TOL)) {
            u.action = 'setpoint';
        }
    }
    if (u.action === 'none') continue;

    setF('lastActionAt' + K, now);
    if (u.action === 'stop') {
        setF('expectedHvac' + K, 'off');
    } else {
        setF('expectedHvac' + K, u.needMode);
        setF('expectedSp' + K, u.targetSp);
        setF('spAt:' + u.id, now);
    }
    setF('lastActionReason' + K, u.desiredReason);
    cmds.push({
        service: u.action === 'stop' ? 'stop' : u.action === 'setpoint' ? 'setpoint' : 'start',
        unit: u.label,
        unitId: u.id,
        hvacModeCmd: u.needMode,
        tempCmd: u.targetSp,
        reason: u.label + ' → '
            + (u.action === 'stop' ? 'arrêt' : u.action === 'setpoint' ? 'consigne ' + u.targetSp + ' °C'
                : u.needMode + ' ' + u.targetSp + ' °C')
            + ' : ' + u.desiredReason,
        payload: { target: { entity_id: u.id } }
    });
}

msg.actions = msg.units.filter(u => u.action !== 'none')
    .map(u => ({ unit: u.label, action: u.action, setpoint: u.action === 'stop' ? null : u.targetSp }));
msg.actionCount = msg.actions.length;

// Historique global (affichage), hors simple modulation de consigne
const majors = msg.actions.filter(a => a.action !== 'setpoint');
if (majors.length > 0) {
    setF('lastActionAt', now);
    setF('lastActionSummary', majors.map(a => a.unit + ' ' + a.action).join(', '));
    setF('lastActionReason', msg.reason);
}
msg.lastActionAt = getF('lastActionAt');
msg.lastActionSummary = getF('lastActionSummary');
msg.lastActionReason = getF('lastActionReason');

return [cmds.length ? cmds : null, msg];

// === Alertes HA (persistent_notification) ===
// Une notification par épisode, anti-spam par contexte persistant.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const out = [];
const now = msg.now;

// 1. Plus aucune température de pièce depuis ≥ 2 h
if ((msg.noTempHours || 0) >= 2) {
    if (!getF('notifNoTemp')) {
        setF('notifNoTemp', true);
        out.push({ payload: {
            notification_id: 'clim_sondes_hs',
            title: 'Clim : plus aucune température de pièce',
            message: 'Aucune unité ne remonte de current_temperature depuis ' + msg.noTempHours
                + ' h. Confort gratuit suspendu (pas de pilotage à l\'aveugle).'
        }});
    }
} else if (msg.anyTempAvailable) {
    setF('notifNoTemp', false);
}

// 2. Unités injoignables depuis ≥ 1 h
const down = (msg.units || []).filter(u => u.available === false && u.breakerOn !== false);
if (down.length > 0) {
    let since = getF('unitsDownSince');
    if (!since) { since = now; setF('unitsDownSince', now); }
    if (now - since > 3600 * 1000) {
        const key = down.map(u => u.id).sort().join(',');
        if (getF('notifUnitsDownKey') !== key) {
            setF('notifUnitsDownKey', key);
            out.push({ payload: {
                notification_id: 'clim_unites_injoignables',
                title: 'Clim : unité(s) injoignable(s)',
                message: down.map(u => u.label).join(', ')
                    + ' indisponible(s) depuis plus d\'une heure, aucune commande envoyée.'
            }});
        }
    }
} else {
    setF('unitsDownSince', null);
    setF('notifUnitsDownKey', null);
}

// 3. Unité en demande mais mode absent de ses hvac_modes (erreur de config)
const unsupported = (msg.units || []).filter(u => u.modeSupported === false);
if (unsupported.length > 0) {
    const key = unsupported.map(u => u.id).sort().join(',');
    if (getF('notifUnsupportedKey') !== key) {
        setF('notifUnsupportedKey', key);
        out.push({ payload: {
            notification_id: 'clim_mode_non_supporte',
            title: 'Clim : mode non exposé par une unité',
            message: unsupported.map(u => u.label + ' (' + u.modes.join(', ') + ')').join(' · ')
                + '. Aucune commande envoyée à ces unités.'
        }});
    }
} else {
    setF('notifUnsupportedKey', null);
}

// 4. Disjoncteur ouvert alors que des pièces de ce groupe auraient du surplus
//    à exploiter. Le besoin des pièces n'est pas testable (entités injoignables
//    disjoncteur coupé) : le signal utile est l'export perdu.
const cutGroups = (msg.groups || []).filter(gr => gr.breakerKnown && !gr.breakerOn);
if (cutGroups.length > 0 && msg.enabled && msg.exportAvg > 500) {
    const key = cutGroups.map(gr => gr.name).sort().join(',');
    if (getF('notifBreakerKey') !== key) {
        setF('notifBreakerKey', key);
        out.push({ payload: {
            notification_id: 'clim_disjoncteur_coupe',
            title: 'Clim : disjoncteur coupé, confort gratuit indisponible',
            message: 'Disjoncteur ' + key + ' hors tension alors que ' + msg.exportAvg
                + ' W partent au réseau. Pièces de ce groupe hors du confort gratuit.'
        }});
    }
} else {
    setF('notifBreakerKey', null);
}

if (out.length === 0) return null;
return [out];

// === Demande de prévision journalière (weather.get_forecasts) ===
// Toutes les heures. Entité météo : CLIM_WEATHER_ENTITY (vide = désactivé).

const id = env.get('CLIM_WEATHER_ENTITY');
const weather = (id === undefined || id === null || id === '') ? 'weather.forecast_maison' : String(id);
if (weather === 'none') return null;
msg.weatherEntity = weather;
msg.payload = { target: { entity_id: [weather] }, data: { type: 'daily' } };
return msg;

// === Mémorisation de la prévision du jour et de demain ===
// Réponse de weather.get_forecasts : { "<entité>": { forecast: [ { datetime,
// temperature, templow, … } ] } }. On n'en garde que les extrêmes du jour et de
// demain, lus par « Lire capteurs & unités » pour décider de la saison.

const STORE = 'file';
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const resp = msg.payload || {};
const entry = resp[msg.weatherEntity] || Object.values(resp)[0] || {};
const list = Array.isArray(entry.forecast) ? entry.forecast : [];
if (list.length === 0) {
    node.warn('Prévision météo vide pour ' + msg.weatherEntity);
    return null;
}
const dayKey = (t) => new Date(t).toDateString();
const today = dayKey(Date.now());
const tomorrow = dayKey(Date.now() + 24 * 3600 * 1000);
const pick = (key) => list.find(f => dayKey(f.datetime) === key) || null;
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? null : Math.round(n * 10) / 10; };
const t0 = pick(today) || list[0];
const t1 = pick(tomorrow) || list[1] || null;
const fc = {
    at: Date.now(),
    todayMax: num(t0.temperature),
    todayMin: num(t0.templow),
    tomorrowMax: t1 ? num(t1.temperature) : null,
    tomorrowMin: t1 ? num(t1.templow) : null
};
setF('forecast', fc);
node.status({ fill: 'green', shape: 'dot', text: fc.todayMin + '–' + fc.todayMax + ' °C' });
return null;

// === Gestion des erreurs du flow (nœud catch) ===

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const src = (msg.error && msg.error.source) || {};
// Nœuds de commande repérés par leur nom : un identifiant en dur ne survit pas
// à un réimport avec renumérotation.
const SERVICE_NODES = ['climate.set_hvac_mode', 'climate.set_temperature', 'climate.turn_off'];

// Commande échouée : l'historique optimiste est faux pour CETTE unité → purge,
// sinon l'anti court-cycle et la détection de pilotage manuel dérivent.
const failedId = msg.payload?.target?.entity_id || msg.unitId;
if (SERVICE_NODES.indexOf(src.name) !== -1 && failedId) {
    const K = ':' + failedId;
    setF('lastActionAt' + K, 0);
    setF('expectedHvac' + K, null);
    setF('expectedSp' + K, null);
    setF('owned' + K, false);
    node.warn('Commande clim échouée sur ' + failedId + ', état du flow purgé');
}

const now = Date.now();
const last = getF('lastErrorNotifAt') || 0;
if (now - last < 15 * 60 * 1000) return null;
setF('lastErrorNotifAt', now);

msg.payload = {
    notification_id: 'clim_flow_error',
    title: 'Clim : erreur dans le flow',
    message: (src.name || src.id || '?') + ' : '
        + (msg.error && msg.error.message ? msg.error.message : 'erreur inconnue')
        + (failedId ? ' (' + failedId + ')' : '')
};
return msg;
